referenceSolutions.javascript:
export function permute(values          )             {
  const sorted=[...values].sort((a,b)=>a-b),result           =[],used=Array         (sorted.length).fill(false); function visit(path         )      { if(path.length===sorted.length) { result.push([...path]);return; } for(let i=0;i<sorted.length;i++)if(!used[i]) { used[i]=true;path.push(sorted[i]);visit(path);path.pop();used[i]=false; } } visit([]);return result;
}

