export function permute(values: number[]): number[][] {
  const sorted=[...values].sort((a,b)=>a-b),result:number[][]=[],used=Array<boolean>(sorted.length).fill(false); function visit(path:number[]):void { if(path.length===sorted.length) { result.push([...path]);return; } for(let i=0;i<sorted.length;i++)if(!used[i]) { used[i]=true;path.push(sorted[i]);visit(path);path.pop();used[i]=false; } } visit([]);return result;
}
